permalink for pages broken for when config.root
in lib/models/page.js
Page.virtual('permalink').get(function() {
    return ctx.config.url + '/' + this.path;
  });
should reflect:
Page.virtual('permalink').get(function() {
    return ctx.config.url + ctx.config.root + this.path;
  });
Somewhat like
  Post.virtual('permalink').get(function() {
    var config = ctx.config;

    return config.url + config.root + this.path;
  });
in lib/models/page.js
Same counts for category.js and tag.js

yAxis min becomes -1 when all points' y values are 0 (stackedAreaChart)
Not sure if this is intentional, but the behavior seems odd, since the default is to always show the yAxis starting at 0, even when some (but not all) points' y values are 0.
See Plunk:
http://plnkr.co/edit/umasgIoekdoWcVjvigHM?p=preview
Seems like it's a result of stackedArea's dependence on scatter:
        // If scale's domain don't have a range, slightly adjust to make one... so a chart can show a single data point
        if (x.domain()[0] === x.domain()[1] || y.domain()[0] === y.domain()[1]) singlePoint = true;
        if (x.domain()[0] === x.domain()[1])
            x.domain()[0] ?
                x.domain([x.domain()[0] - x.domain()[0] * 0.01, x.domain()[1] + x.domain()[1] * 0.01])
                : x.domain([-1,1]);

        if (y.domain()[0] === y.domain()[1])
            y.domain()[0] ?
                y.domain([y.domain()[0] - y.domain()[0] * 0.01, y.domain()[1] + y.domain()[1] * 0.01])
                : y.domain([-1,1]);

        if ( isNaN(x.domain()[0])) {
            x.domain([-1,1]);
        }

        if ( isNaN(y.domain()[0])) {
            y.domain([-1,1]);
        }

